#' Global Spatial Autocorrelation
#'
#' 
#' @param data .
#' @param vars .
#' @param idVar .
#' @param xVar .
#' @param yVar .
#' @param wSource .
#' @param wFile .
#' @param wIdField .
#' @param wMethod .
#' @param wK .
#' @param wDist .
#' @param wPower .
#' @param wCutoff .
#' @param wOrder .
#' @param wCumul .
#' @param wSymm .
#' @param wLonLat .
#' @param wStyle .
#' @param showGuide .
#' @param showHelp .
#' @param inference .
#' @param alt .
#' @param nperm .
#' @param seed .
#' @param geary .
#' @param getisG .
#' @param scatter .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$global} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$scatterPlots} \tab \tab \tab \tab \tab an array of images \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$global$asDF}
#'
#' \code{as.data.frame(results$global)}
#'
#' @export
moran <- function(
    data,
    vars,
    idVar,
    xVar,
    yVar,
    wSource = "coords",
    wFile = "",
    wIdField = "",
    wMethod = "auto",
    wK = 5,
    wDist = 0,
    wPower = 1,
    wCutoff = 0,
    wOrder = 1,
    wCumul = FALSE,
    wSymm = FALSE,
    wLonLat = FALSE,
    wStyle = "W",
    showGuide = FALSE,
    showHelp = FALSE,
    inference = "randomisation",
    alt = "two.sided",
    nperm = 999,
    seed = 1,
    geary = FALSE,
    getisG = FALSE,
    scatter = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("moran requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(idVar)) idVar <- jmvcore::resolveQuo(jmvcore::enquo(idVar))
    if ( ! missing(xVar)) xVar <- jmvcore::resolveQuo(jmvcore::enquo(xVar))
    if ( ! missing(yVar)) yVar <- jmvcore::resolveQuo(jmvcore::enquo(yVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(idVar), idVar, NULL),
            `if`( ! missing(xVar), xVar, NULL),
            `if`( ! missing(yVar), yVar, NULL))


    options <- moranOptions$new(
        vars = vars,
        idVar = idVar,
        xVar = xVar,
        yVar = yVar,
        wSource = wSource,
        wFile = wFile,
        wIdField = wIdField,
        wMethod = wMethod,
        wK = wK,
        wDist = wDist,
        wPower = wPower,
        wCutoff = wCutoff,
        wOrder = wOrder,
        wCumul = wCumul,
        wSymm = wSymm,
        wLonLat = wLonLat,
        wStyle = wStyle,
        showGuide = showGuide,
        showHelp = showHelp,
        inference = inference,
        alt = alt,
        nperm = nperm,
        seed = seed,
        geary = geary,
        getisG = getisG,
        scatter = scatter)

    analysis <- moranClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

